commands.command:
set -euo pipefail; EXPECTED='eb10cdd70039e82d09cc03231b52ad851fe42546'; PKG='io.blueeye'; git fetch --no-tags origin main >/dev/null; test "$(git rev-parse origin/main)" = "${EXPECTED}"; SERIAL=$(adb devices | awk 'NR>1 && $2=="device" {print $1}' | head -n1); test -n "${SERIAL}"; echo '--- granted runtime permissions ---'; adb -s "${SERIAL}" shell dumpsys package "${PKG}" | grep -E 'android.permission.(BLUETOOTH_SCAN|BLUETOOTH_CONNECT|ACCESS_FINE_LOCATION|ACCESS_COARSE_LOCATION|POST_NOTIFICATIONS).*granted=' || true; echo '--- bluetooth state ---'; adb -s "${SERIAL}" shell settings get global bluetooth_on; adb -s "${SERIAL}" shell dumpsys bluetooth_manager | grep -E -m 12 'enabled:|state:|mEnable|name:' || true; echo '--- current UI text/semantics ---'; TMP=$(mktemp -d); trap 'rm -rf "${TMP}"' EXIT; adb -s "${SERIAL}" shell uiautomator dump /sdcard/blueeye-window.xml >/dev/null; adb -s "${SERIAL}" pull /sdcard/blueeye-window.xml "${TMP}/window.xml" >/dev/null; python3 - "${TMP}/window.xml" <<'PY'
import sys, xml.etree.ElementTree as ET
root=ET.parse(sys.argv[1]).getroot()
seen=[]
for n in root.iter('node'):
    t=(n.attrib.get('text') or '').strip(); d=(n.attrib.get('content-desc') or '').strip()
    for kind,val in [('text',t),('desc',d)]:
        if val and (kind,val) not in seen:
            seen.append((kind,val))
for kind,val in seen[:160]: print(f'{kind}: {val}')
PY
echo '--- app services/process ---'; adb -s "${SERIAL}" shell pidof "${PKG}" || true; adb -s "${SERIAL}" shell dumpsys activity services "${PKG}" | grep -E -m 80 'ServiceRecord|foreground|io.blueeye|bluetooth|scan' || true; echo 'PHONE_STATE_CAPTURE=PASS'
